verification_steps.command:
node --input-type=module -e '
import { persist, logWrite } from "./src/store.js";
import { readFileSync, existsSync } from "node:fs";

let threw = false;
try { persist({}); } catch (e) { threw = e.message === "order.id required"; }
if (!threw) throw new Error("expected persist to require order.id");

const a = persist({ id: "ord-1", total: 12 });
if (!a.ok || a.id !== "ord-1") throw new Error("persist return");

const b = persist({ id: "ord-2", total: 40 });
if (!b.ok) throw new Error("second persist");

const orders = JSON.parse(readFileSync("data/orders.json", "utf8"));
if (!orders["ord-1"] || orders["ord-1"].total !== 12) throw new Error("ord-1 missing");
if (!orders["ord-2"] || orders["ord-2"].total !== 40) throw new Error("ord-2 missing");

const logged = logWrite({ action: "manual", id: "ord-1" });
if (logged !== "json") throw new Error("logWrite should return json");

const lines = readFileSync("data/writes.log", "utf8").trim().split("\n");
if (lines.length < 3) throw new Error("expected persist logs plus manual");
for (const line of lines) JSON.parse(line);

if (!existsSync("docs/adr/0002-file-store.md")) throw new Error("ADR missing");
console.log("ok", { orders: Object.keys(orders), logLines: lines.length });
'
